const FS_pts=(f,t0,t1,x0,x1,yc,k,n=160)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return p};
/* a curve of computed points: f(t) for t in [t0,t1], mapped to x in [x0,x1] and y = yc - k*f */
const FS_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=160,ex='')=>`<polyline points="${FS_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
/* the area between the curve and the axis, filled */
const FS_area=(f,t0,t1,x0,x1,yc,k,col,op=.25,n=160)=>`<polygon points="${x0},${yc} ${FS_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')} ${x1},${yc}" fill="${col}" fill-opacity="${op}" stroke="none"/>`;
/* stems of computed values: v = [[position, value], ...] */
const FS_stems=(v,xc,dx,yc,k,col,r=7,w=4)=>v.map(([p,q])=>{const x=xc+p*dx,y=yc-k*q;return FS_L(x,yc,x,y,col,w)+`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r}" fill="${col}"/>`}).join('');
const FS_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return FS_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const FS_X=(x,y,s,col)=>FS_L(x-s,y-s,x+s,y+s,col,6)+FS_L(x-s,y+s,x+s,y-s,col,6);
