/* a square wave that is even and half-wave symmetric: +1 for |t| < T/4, -1 for T/4 < |t| < T/2 (period 1) */
const FS_sq=t=>{const u=((t%1)+1.5)%1-0.5;return Math.abs(u)<0.25?1:-1};
const FS_sqv=(x0,x1,yc,k,per,t0)=>{/* the square wave FS_sq with vertical edges, from t0 at x0 to x1, per px per period */const t1=t0+(x1-x0)/per,X=t=>(x0+(t-t0)*per).toFixed(1),Y=t=>(yc-k*FS_sq(t)).toFixed(1);let p=[`${X(t0)},${Y(t0+1e-6)}`],e=Math.floor((t0-0.25)*2)/2+0.25;while(e<=t0+1e-9)e+=0.5;while(e<t1-1e-9){p.push(`${X(e)},${Y(e-1e-6)}`,`${X(e)},${Y(e+1e-6)}`);e+=0.5}p.push(`${X(t1)},${Y(t1-1e-6)}`);return p.join(' ')};

